for p in products:
    if p not in revenue or p not in demand or p not in inventory:
        raise ValueError(f'Missing data for product: {p}')
m = gp.Model('Dairy_Fulfillment')
x = m.addVars(products, vtype=GRB.INTEGER, lb=0, name='')
for p in products:
    upper = min(demand[p], inventory[p])
    m.addConstr(x[p] <= upper, name=f'ub_{p}')
m.setObjective(gp.quicksum((revenue[p] * x[p] for p in products)), GRB.MAXIMIZE)
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')